import { render } from '@testing-library/react';
import React from 'react';
import { ProgressTracker } from '../../../../../..';

describe('StepLabel', () => {
  it('should be shown a console warn when the ProgressTracker.StepLabel is called outside a ProgressTracker.Step, ProgressTracker.Header and ProgressTracker.Root component', () => {
    jest.spyOn(console, 'warn').mockImplementation();
    render(<ProgressTracker.StepLabel />);
    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining(
        'Make sure of ProgressTracker.StepLabel component is subcomponent of ProgressTracker.Step, ProgressTracker.Header and ProgressTracker.Root.'
      )
    );
  });
});
